# Comprehensive: find all docs of type Market Research Report, and detect product name in content
# Also search for explicit CoachForce<->CoFoAIX linking phrases across all files
print("=== All Market Research Report docs: id, file, first 90 chars ===")
for path in sorted(glob.glob('workspace/DATA/products/*.json')):
    with open(path) as f:
        d = json.load(f)
    for doc in d.get('documents', []):
        if 'market research' in doc.get('type','').lower():
            print(f"[{os.path.basename(path)}] id={doc['id']} | {doc.get('content','')[:90]}")

print("\n=== Search for linking phrases (CoachForce / CoFoAIX co-occurrence) ===")
# Search every file's raw text for lines containing both, or 'CoachForce' near 'CoFoAIX'
for path in sorted(glob.glob('workspace/DATA/products/*.json')):
    with open(path) as f:
        raw = f.read()
    # find sentences containing both
    hits = set()
    for m in re.finditer(r'[^.]*CoachForce[^.]*CoFoAIX[^.]|[^.]*CoFoAIX[^.]*CoachForce[^.]', raw):
        s = m.group(0).strip()
        if len(s) < 300:
            hits.add(s[:250])
    if hits:
        print(f"\n[{os.path.basename(path)}]")
        for h in list(hits)[:5]:
            print("   ", h)
